declare const require: (name: string) => any;
const limitEnforced = (() => { try { const fs = require('fs'); fs.writeFileSync('/tmp/conformance-fill', 'x'.repeat(32 * 1024 * 1024)); fs.unlinkSync('/tmp/conformance-fill'); return false; } catch { return true; } })();
export function chooseMove(turn: number, myHistory: string, opponentHistory: string, rng: { nextInt(limit: number): number }): string { return limitEnforced ? 'R' : 'X'; }
